// Claude's review tests for A43 batch 2 in the browser. agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

async function open(mocks: Mock[]): Promise<Page> {
  const p: Project = { id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default', scenarios: [{ id: 'default', name: 'Default', mocks }] };
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  return page;
}

// The fixture's /api/broken-body sends headers and half a body, then cuts the connection;
// /api/hits?name=broken-body says how many times it was called.
const hits = (page: Page) => page.evaluate(async () => Number(await (await fetch('/api/hits?name=broken-body')).text()));

test('#5 XHR Change real never sends the request twice when the real body breaks', async () => {
  const patch: Mock = {
    id: 'p', name: 'p', enabled: true, method: 'POST', urlPattern: '/api/broken-body', reply: 'patch', patch: { status: 201 }, source: 'manual', createdAt: 0,
    response: { status: 200, headers: {}, body: '', bodyEncoding: 'text', delayMs: 0 },
  };
  const page = await open([patch]);
  try {
    const before = await hits(page);
    const xhr = await page.evaluate(() => new Promise<string>((resolve) => {
      const x = new XMLHttpRequest();
      x.open('POST', '/api/broken-body');
      x.onload = () => resolve(`load ${x.status}`);
      x.onerror = () => resolve(`error ${x.status} ${x.readyState}`);
      x.send('order');
    }));
    expect(xhr).toBe('error 0 4');
    expect((await hits(page)) - before).toBe(1);

    const before2 = await hits(page);
    const viaFetch = await page.evaluate(async () => {
      try {
        const r = await fetch('/api/broken-body', { method: 'POST', body: 'order' });
        return `ok ${r.status}`;
      } catch (e) {
        return (e as Error).name;
      }
    });
    expect(viaFetch).toBe('TypeError');
    expect((await hits(page)) - before2).toBe(1);
  } finally {
    await page.close();
  }
});

test('#6 an XHR mock whose body cannot be built falls back to a real, normal XHR', async () => {
  const bad: Mock = {
    id: 'b', name: 'b', enabled: true, method: 'GET', urlPattern: '/api/goals', source: 'manual', createdAt: 0,
    response: { status: 200, headers: {}, body: '!!', bodyEncoding: 'base64', delayMs: 0 },
  };
  const page = await open([bad]);
  try {
    const got = await page.evaluate(() => new Promise<{ status: number; readyState: number; text: string }>((resolve) => {
      const x = new XMLHttpRequest();
      x.open('GET', '/api/goals');
      x.onloadend = () => resolve({ status: x.status, readyState: x.readyState, text: x.responseText });
      x.send();
    }));
    expect(got).toEqual({ status: 200, readyState: 4, text: '{"source":"server"}' });
  } finally {
    await page.close();
  }
});
